        due = pdate(b.get('lastPayDate'))
        nsd = pdate(b.get('nextStatementDate'))
        ndue = pdate(b.get('nextLastPayDate'))
        vars['sel_statement_date'] = str(b.get('statementDate') or '')
        blocks = []
        for code, key, nm in (('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')):
            blk = b.get(key)
            if isinstance(blk, dict) and blk:
                blocks.append((code, nm, blk))
        pdfcur = 'TL'
        for code, nm, blk in blocks:
            if num(blk.get('remainingDebt')) > 0 or num(blk.get('statementDebt')) > 0:
                pdfcur = code
                break
        vars['pdf_currency'] = pdfcur
        top = str(b.get('statementPaymentStatus') or '')
        any_debt = any(num(blk.get('remainingDebt')) > 0 for code, nm, blk in blocks)
        parts = []
        if sd is None or top == 'NO_DEBT' or not any_debt:
            tl = [blk for code, nm, blk in blocks if code == 'TL']
            if sd is None:
                parts.append(intro + 'da ödenmemiş bir ekstre borcunuz bulunmamaktadır.')
            else:
                parts.append(intro + 'ın ' + sdate(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır.')
            if tl and num(tl[0].get('totalDebt')) > 0:
                parts.append('Gelecek dönemler dahil toplam borcunuz ' + cop(amt(tl[0].get('totalDebt'), 'TL')) + '.')
            nd = ndue if ndue else due
            if nd and sd is not None:
                parts.append('Son ödeme tarihiniz ' + sdate(nd) + ' olacaktır.')
            vars['reading_kind'] = 'nodebt'
        else:
            vars['reading_kind'] = 'debt'
            if (nsd and nsd == t) or (sd and sd == t):
                parts.append(intro + ' için hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
                tots = []
                for code, nm, blk in blocks:
                    if num(blk.get('totalDebt')) > 0:
                        tots.append(nm + ' cinsinden ' + amt(blk.get('totalDebt'), code))
                if tots:
                    parts.append('Toplam borcunuz ' + ', '.join(tots) + '.')
            elif due and t > due:
                parts.append(intro + ' için ' + sdate(sd) + ' tarihinde kesilen ekstrenin son ödeme tarihi olan ' + sdate(due) + ' geçmiştir.')
                tots = []
                for code, nm, blk in blocks:
                    if num(blk.get('totalDebt')) > 0:
                        tots.append(nm + ' cinsinden ' + amt(blk.get('totalDebt'), code))
                if tots:
                    parts.append('Toplam borcunuz ' + ', '.join(tots) + '.')
            else:
                prefix = intro + 'a ait ' + sdate(sd) + ' tarihinde kesilen ekstre '
                first = True
                clear = []
                for code, nm, blk in blocks:
                    sdb = num(blk.get('statementDebt'))
                    mp = num(blk.get('minPayment'))
                    rd = num(blk.get('remainingDebt'))
                    rm = num(blk.get('remainingMinPayment'))
                    if rd <= 0:
                        clear.append(nm)
                        continue
                    if code == 'TL':
                        X = amt(sdb, 'TL')
                        if rm <= 0:
                            s = 'Türk Lirası borcunuz ' + X + ', kalan toplam borcunuz ' + cop(amt(rd, 'TL')) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                        elif rm >= mp:
                            s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + cop(amt(mp, 'TL')) + '.'
                        else:
                            s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + amt(mp, 'TL') + ', kalan toplam borcunuz ' + amt(rd, 'TL') + ', kalan minimum ödeme tutarınız ' + cop(amt(rm, 'TL')) + '.'
                    else:
                        s = nm + ' borcunuz ' + amt(sdb, code) + ', kalan toplam borcunuz ' + amt(rd, code) + ', ödenmesi gereken minimum tutar ' + cop(amt(mp, code)) + '.'
                    if first:
                        s = prefix + s
                        first = False
                    parts.append(s)
                if clear:
                    if len(clear) == 1:
                        cs = clear[0]
                    else:
                        cs = ', '.join(clear[:-1]) + ' ve ' + clear[-1]
                    parts.append(cs + ' borcunuz bulunmamaktadır.')
            tlb = [blk for code, nm, blk in blocks if code == 'TL']
            if due and t > due and str(b.get('automaticPaymentFlag') or '') == 'Y' and tlb and num(tlb[0].get('remainAutomaticPaymentAmount')) > 0:
                parts.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + cop(amt(tlb[0].get('remainAutomaticPaymentAmount'), 'TL')) + '.')
            if due and t == due:
                parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            elif due and t < due:
                parts.append('Borçlarınız için son ödeme tarihiniz ' + sdate_cop(due) + '.')
        vars['reading_text'] = ' '.join(parts)
        vars['due_text'] = sdate(due) if due else ''
except Exception:
    vars['bal_route'] = 'error'
    vars['reading_text'] = ''
